def first_numeric_value(fragment):
    buffer = ''
    started = False
    for character in fragment:
        if character.isdigit():
            buffer += character
            started = True
        elif started and character in '.,':
            buffer += character
        elif started:
            break
    cleaned = buffer.replace(',', '').rstrip('.')
    if not cleaned or cleaned.count('.') > 1:
        return None
    value = float(cleaned)
    return value if value > 0 else None
def extract_receipt_amount(content):
    lowered = content.lower()
    amount_markers = ['total amount paid', 'amount paid', 'grand total', 'total due', 'amount due', 'total amount', 'balance due', 'total', 'amount']
    for marker in amount_markers:
        search_from = 0
        while True:
            marker_index = lowered.find(marker, search_from)
            if marker_index < 0:
                break
            line_end = content.find('\n', marker_index)
            if line_end < 0:
                line_end = min(len(content), marker_index + len(marker) + 80)
            value = first_numeric_value(content[marker_index + len(marker):line_end])
            if value is not None:
                return value
            search_from = marker_index + len(marker)
    dollar_index = content.find('$')
    if dollar_index >= 0:
        return first_numeric_value(content[dollar_index + 1:dollar_index + 40])
    return None
